// Patch 3a: filter Postgres v2 zero-row phantom ({success:true}) out of the digest.
// Real listings always have a numeric id; phantoms never do.
const rows = $input.all().map(i => i.json).filter(r => r && r.id);

// Patch 4: pull coverage stats from upstream node for the email health banner.
// Window matches the digest SELECT (date_seen >= today - 8 days). Ints are returned
// as strings by node-postgres for COUNT/bigint, so coerce defensively.
const statsRaw = $('Postgres: Get Coverage Stats').first().json || {};
const stats = {
  total_seen: Number(statsRaw.total_seen || 0),
  with_body: Number(statsRaw.with_body || 0),
  quarantined: Number(statsRaw.quarantined || 0),
  scored: Number(statsRaw.scored || 0)
};

const escapeHtml = (s) => String(s || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

// P1: human-readable labels for the structured cap_reason enum (shared vocabulary
// with the scorer in scoring-prompt.md and the P2 Telegram reason-chips).
const capLabels = {
  non_berlin: 'non-Berlin location',
  hybrid: 'hybrid / on-site, non-Berlin office',
  no_remote: 'no remote option',
  too_senior: 'seniority stretch',
  comp_below_floor: 'comp below floor',
  language: 'non-English language gate'
};

const seen = new Map();
for (const r of rows) {
  const key = `${(r.title || '').toLowerCase().trim()}|${(r.company || '').toLowerCase().trim()}`;
  const existing = seen.get(key);
  if (!existing) {
    seen.set(key, r);
  } else if (existing.source === 'linkedin' && r.source !== 'linkedin') {
    seen.set(key, r);
  }
}
const deduped = Array.from(seen.values());

deduped.sort((a, b) => (b.score || 0) - (a.score || 0));

// P1: tier the digest. Strong = score >= 8; Worth a look = 6-7 (borderline, usually
// pulled down by a hard cap). cap_reason is rendered only on Worth-a-look rows.
const strong = deduped.filter(r => (r.score || 0) >= 8);
const worth = deduped.filter(r => (r.score || 0) >= 6 && (r.score || 0) < 8);

const today = new Date().toLocaleDateString('en-GB', {
  timeZone: 'Europe/Berlin',
  year: 'numeric', month: 'long', day: 'numeric'
});

const subject = `Job Radar: ${strong.length} strong, ${worth.length} worth a look (${today})`;

const cardHtml = (r, showCap) => {
  const scoreBadge = `<span style="background:#0a66c2;color:#fff;padding:3px 10px;border-radius:4px;font-weight:bold;font-size:14px;">${r.score}/10</span>`;
  const sourceTag = `<span style="color:#666;font-size:11px;margin-left:8px;text-transform:uppercase;">${escapeHtml(r.source)}</span>`;
  const capChip = (showCap && r.cap_reason && capLabels[r.cap_reason])
    ? `<span style="background:#fff4e5;color:#b54708;border:1px solid #f5c98a;padding:2px 8px;border-radius:4px;font-size:11px;margin-left:8px;">&#9888; capped: ${escapeHtml(capLabels[r.cap_reason])}</span>`
    : '';
  return `
    <div style="border:1px solid #ddd;border-radius:8px;padding:14px;margin-bottom:12px;font-family:Arial,sans-serif;">
      <div style="margin-bottom:6px;">${scoreBadge}${sourceTag}${capChip}</div>
      <div style="font-size:16px;font-weight:bold;margin-bottom:4px;">
        <a href="${escapeHtml(r.url)}" style="color:#0a66c2;text-decoration:none;">${escapeHtml(r.title || 'Untitled role')}</a>
      </div>
      <div style="font-size:13px;color:#333;margin-bottom:8px;">${escapeHtml(r.company || 'Unknown')}</div>
      <div style="font-size:13px;color:#555;line-height:1.4;">${escapeHtml(r.rationale || '')}</div>
    </div>`;
};

const sectionHtml = (label, items, showCap) => {
  if (items.length === 0) return '';
  return `
    <h3 style="margin:20px 0 10px 0;font-size:15px;color:#111;border-bottom:2px solid #0a66c2;padding-bottom:4px;">${label} (${items.length})</h3>
    ${items.map(r => cardHtml(r, showCap)).join('')}`;
};

// Coverage banner: surfaces the body-coverage health of this scoring window.
// Rendered only when the digest sends (count > 0); zero-match runs skip the email.
const bodyPct = stats.total_seen > 0
  ? Math.round((stats.with_body / stats.total_seen) * 100)
  : 0;
const coverageBanner = `
    <div style="background:#f0f6ff;border-left:3px solid #0a66c2;padding:10px 12px;margin-bottom:16px;font-size:12px;color:#444;line-height:1.5;">
      <strong style="color:#0a66c2;">Coverage</strong> &middot;
      ${stats.total_seen} seen this week &middot;
      ${stats.with_body} with body (${bodyPct}%) &middot;
      ${stats.scored} scored &middot;
      ${stats.quarantined} quarantined (no body)
    </div>`;

const html = `<!DOCTYPE html><html><body style="margin:0;padding:16px;background:#f6f6f6;font-family:Arial,sans-serif;">
  <div style="max-width:640px;margin:0 auto;">
    <h2 style="margin:0 0 16px 0;font-size:18px;">Job Radar &mdash; ${today}</h2>
    <p style="margin:0 0 12px 0;font-size:13px;color:#666;">
      ${strong.length} strong (8+), ${worth.length} worth a look (6&ndash;7).
    </p>
    ${coverageBanner}
    ${sectionHtml('Strong matches', strong, false)}
    ${sectionHtml('Worth a look', worth, true)}
    <p style="margin-top:24px;font-size:11px;color:#999;">Sent by 05b - Digest Email</p>
  </div>
</body></html>`;

return [{ json: { subject, html, count: deduped.length, included_ids: deduped.map(r => r.id), stats } }];
